function msg(t,err=false){statusText.textContent=t;statusText.parentElement.classList.toggle('error',err)}function bar(t,p,err=false){progress.classList.add('show');progress.classList.toggle('error',err);progressText.textContent=t;progressPercent.textContent=p+'%';progressBar.style.width=p+'%'}function ready(v=true){generate.disabled=!v;generate.innerHTML=(v?'开始合成':'上传图片后开始合成')+' <span>→</span>'}function loadImg(src){return new Promise((ok,fail)=>{const i=new Image;i.onload=()=>ok(i);i.onerror=fail;i.src=src})}function cover(img,w,h){const s=Math.max(w/img.width,h/img.height),iw=img.width*s,ih=img.height*s;return[(w-iw)/2,(h-ih)/2,iw,ih]}function contain(img,w,h,f=.48){const s=Math.min(w*f/img.width,h*f/img.height);return[img.width*s,img.height*s]}
function renderTemplates(){templates.innerHTML='';MATERIALS.forEach((m,i)=>{const b=document.createElement('button');b.className='template asset'+(i===0?' selected':'');b.type='button';b.dataset.i=i;b.style.backgroundImage=`url("${m.src}")`;b.innerHTML=`<span>${m.label}</span>`;b.onclick=async()=>{[...templates.children].forEach(x=>x.classList.remove('selected'));b.classList.add('selected');bgImage=await loadImg(m.src);draw()};templates.appendChild(b)});loadImg(MATERIALS[0].src).then(i=>{bgImage=i;draw()})}
async function professionalCut(file){const fd=new FormData();fd.append('image_file',file);fd.append('size','auto');const r=await fetch('/api/remove-bg',{method:'POST',body:fd});if(!r.ok){let j={};try{j=await r.json()}catch{}throw new Error(j.error||'专业抠图失败')}return URL.createObjectURL(await r.blob())}
async function processSubject(){if(!sourceFile)return;bar(mode==='professional'?'正在专业抠图':'正在处理主体',18);try{let url=sourceUrl;if(mode==='professional')url=await professionalCut(sourceFile);else if(mode==='local')url=await localCut(sourceImage);subjectImage=await loadImg(url);bar('主体处理完成',60);draw();msg(mode==='professional'?'专业抠图完成，可以合成':'主体已就绪，可以合成')}catch(e){subjectImage=sourceImage;bar('专业抠图失败，已保留原图',0,true);msg('专业抠图失败：'+e.message,true);draw()}}
async function localCut(img){const c=document.createElement('canvas'),x=c.getContext('2d',{willReadFrequently:true});c.width=img.width;c.height=img.height;x.drawImage(img,0,0);const d=x.getImageData(0,0,c.width,c.height),p=d.data;for(let i=0;i<p.length;i+=4){const r=p[i],g=p[i+1],b=p[i+2],mx=Math.max(r,g,b),mn=Math.min(r,g,b);if(mx>205&&mx-mn<38)p[i+3]=0}x.putImageData(d,0,0);return c.toDataURL('image/png')}
function draw(final=false){if(!bgImage&&!bgColor)return;if(!canvas.width){canvas.width=1000;canvas.height=1000}ctx.clearRect(0,0,1000,1000);if(bgImage){const r=cover(bgImage,1000,1000);ctx.drawImage(bgImage,...r)}else{ctx.fillStyle=bgColor;ctx.fillRect(0,0,1000,1000)}if(!subjectImage)return;const sc=Number(scale.value)/100,deg=Number(rotate.value)*Math.PI/180,[iw,ih]=contain(subjectImage,1000,1000,.46*sc),cx=500+pos.x,cy=620+pos.y;ctx.save();ctx.translate(cx,cy);ctx.rotate(deg);if(useShadow){ctx.shadowColor='rgba(0,0,0,.22)';ctx.shadowBlur=30;ctx.shadowOffsetY=20}ctx.drawImage(subjectImage,-iw/2,-ih/2,iw,ih);ctx.restore();canvas.hidden=false;empty.hidden=true;if(final){resultUrl=canvas.toDataURL('image/jpeg',.94);download.href=resultUrl;download.download='baijing-background.jpg';download.classList.remove('disabled');download.setAttribute('aria-disabled','false')}}
