fileInput.onchange=e=>loadFile(e.target.files[0]);drop.onclick=()=>fileInput.click();replace.onclick=()=>fileInput.click();drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0])};subjectMode.onclick=e=>{if(e.target.tagName!=='BUTTON')return;[...subjectMode.children].forEach(b=>b.classList.remove('selected'));e.target.classList.add('selected');mode=e.target.dataset.value;processSubject()};swatches.onclick=e=>{const b=e.target.closest('.swatch');if(!b)return;[...swatches.children].forEach(x=>x.classList.remove('selected'));b.classList.add('selected');bgColor=b.dataset.color;bgImage=null;[...templates.children].forEach(x=>x.classList.remove('selected'));draw()};scale.oninput=()=>{scaleValue.textContent=scale.value+'%';draw()};rotate.oninput=()=>{rotateValue.textContent=rotate.value+'°';draw()};shadow.onclick=()=>{useShadow=!useShadow;shadow.classList.toggle('on',useShadow);draw()};generate.onclick=()=>{if(!subjectImage){fileInput.click();return}bar('合成完成',100);draw(true);msg('合成完成，可以下载')};canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,px:pos.x,py:pos.y};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const r=canvas.getBoundingClientRect(),k=1000/r.width;pos.x=drag.px+(e.clientX-drag.x)*k;pos.y=drag.py+(e.clientY-drag.y)*k;draw()};canvas.onpointerup=()=>drag=null;bgFile.onchange=async e=>{const f=e.target.files[0];if(!f)return;bgImage=await loadImg(URL.createObjectURL(f));draw()};document.querySelector('[data-value="local"]').classList.remove('selected');document.querySelector('[data-value="professional"]').classList.add('selected');renderTemplates();ready(false);
